#!/bin/bash
# TFT test server setup, generated by vps/make-launch-script.py. Holds no secret.
# Downloads the setup, stops unless it has exactly this hash, then runs it as root.
set -eu
mkdir -p /opt/tftvps
curl -fsSL --retry 5 -o /opt/tftvps/payload.tar https://raw.githubusercontent.com/hadi2trade1995-spec/scratch-trees-setup/main/payload.tar
echo "b6c01bd33447abaa3b81ff894fc2967d29153db192a94d3457e9ba5099a39e2a  /opt/tftvps/payload.tar" | sha256sum --strict --check
echo "tftvps setup: received b6c01bd33447abaa3b81ff894fc2967d29153db192a94d3457e9ba5099a39e2a" | tee /dev/console
tar -xf /opt/tftvps/payload.tar -C /opt/tftvps --no-same-owner
rm -f /opt/tftvps/payload.tar
nohup bash /opt/tftvps/setup.sh >/var/log/tftvps-setup.log 2>&1 &
